8	/** The due figures of claims and the due-total of a person's claims. */
9	public final class Dues {
10	
11	    private Dues() {
12	    }
13	
14	    /**
15	     * A claim's due figure: once settled, the due fixed then; while bound by a statement, the figure
16	     * bound then; otherwise the amount at the rate for its person's grade in force on its date, but at
17	     * least the sheet's floor. Null when there is none.
18	     */
19	    public static BigDecimal figure(Claim claim, String grade, RateTable rates) {
20	        if (claim.getSettledDue() != null) {
21	            return claim.getSettledDue();
22	        }
23	        return claim.isStated() ? claim.getStatedDue()
24	                : rates.due(claim.getAmount(), grade, claim.getDate());
25	    }
26	
27	    /** Whether the claim is overdue: OPEN, and due by a date before the sheet's today. */
28	    public static boolean overdue(Claim claim, RateTable rates) {
29	        return claim.getStatus() == ClaimStatus.OPEN && rates.dueBy(claim.getDate()).isBefore(rates.today());
30	    }
31	
32	    /** The overdue claims that count, see {@link #overdue} and {@link #counts}. */
33	    public static List<Claim> overdue(List<Claim> claims, RateTable rates, boolean held) {
34	        return claims.stream().filter(c -> counts(c, held) && overdue(c, rates)).toList();
35	    }
36	
37	    /** The sum of the due figures of the claims given (0.00 with none); a claim with none is skipped. */
38	    public static BigDecimal sum(String grade, List<Claim> claims, RateTable rates) {
39	        return claims.stream().map(c -> figure(c, grade, rates)).filter(Objects::nonNull)
40	                .reduce(BigDecimal.ZERO, BigDecimal::add);
41	    }
42	
43	    /** Whether the claim's figure is kept whatever the rates: fixed by settling or bound by a statement. */
44	    private static boolean kept(Claim claim) {
45	        return claim.getSettledDue() != null || (claim.isStated() && claim.getStatedDue() != null);
46	    }
47	
48	    /**
49	     * Whether the claim counts in the live totals: OPEN and SETTLED claims do, except that the OPEN
50	     * claims of a person on hold count in none.
51	     */
52	    public static boolean counts(Claim claim, boolean held) {
53	        return claim.getStatus().counts() && !(held && claim.getStatus() == ClaimStatus.OPEN);
54	    }
55	
56	    /**
57	     * The sum of the due figures of the claims that count (0.00 with none); a person not on hold.
58	     */
59	    public static BigDecimal total(String grade, List<Claim> claims, RateTable rates) {
60	        return total(grade, claims, rates, false);
61	    }
62	
63	    /**
64	     * The sum of the due figures of the claims that count (0.00 with none), see {@link #counts}. Null (n/a) when the grade has
65	     * no rate on the sheet's today, unless a claim that counts keeps a figure: then it is the sum of the
66	     * figures there are.
67	     */
68	    public static BigDecimal total(String grade, List<Claim> claims, RateTable rates, boolean held) {
69	        List<Claim> counting = claims.stream().filter(c -> counts(c, held)).toList();
70	        boolean shown = rates.current(grade) != null || counting.stream().anyMatch(Dues::kept);
71	        return shown ? counting.stream().map(c -> figure(c, grade, rates))
72	                .filter(Objects::nonNull).reduce(BigDecimal.ZERO, BigDecimal::add) : null;
73	    }
