237	import java.math.BigDecimal;
238	import java.time.LocalDate;
239	import java.util.List;
240	import java.util.Map;
241	import java.util.stream.Collectors;
242	import net.officefloor.hq.app.access.AccessService;
243	import net.officefloor.hq.app.period.PeriodService;
244	import net.officefloor.hq.app.person.PersonRepository;
245	import net.officefloor.hq.app.sheet.SheetService;
246	import net.officefloor.hq.app.person.Person;
247	import net.officefloor.hq.app.rate.RateService;
248	import net.officefloor.hq.app.rollup.Rollup;
249	import org.springframework.context.ApplicationEventPublisher;
250	import org.springframework.http.HttpStatus;
251	import org.springframework.stereotype.Service;
252	import org.springframework.transaction.annotation.Transactional;
253	import org.springframework.web.server.ResponseStatusException;
254	
255	/**
256	 * The claims on a sheet: listed per person newest first, added, edited and moved through their
257	 * statuses one at a time. Only a DRAFT can be edited. A voided claim keeps
258	 * its number, which is never reused. Settling a claim fixes its due at the rate its person's grade has then on the claim's date
259	 * (at least the sheet's floor then), or at the
260	 * figure a statement bound it to. No claim dated inside a closed period can be added, edited or moved,
261	 * and no claim dated after its person's retirement date can be added or edited to that date. A clerk
262	 * cannot settle a claim whose due is above the sheet's clerk limit; a steward settles anything.
263	 */
264	@Service
265	public class ClaimService {
266	
267	    private final ClaimRepository claims;
268	    private final PersonRepository people;
269	    private final SheetService sheets;
270	    private final RateService rates;
271	    private final Rollup rollup;
272	    private final PeriodService periods;
273	    private final AccessService access;
274	    private final ApplicationEventPublisher events;
275	
276	    public ClaimService(ClaimRepository claims, PersonRepository people, SheetService sheets,
277	            RateService rates, Rollup rollup, PeriodService periods, AccessService access,
278	            ApplicationEventPublisher events) {
279	        this.access = access;
280	        this.rollup = rollup;
281	        this.periods = periods;
282	        this.claims = claims;
283	        this.people = people;
284	        this.sheets = sheets;
285	        this.rates = rates;
286	        this.events = events;
287	    }
288	
289	    /** Every claim on the sheet by the person who made it, each person's newest first. */
290	    @Transactional(readOnly = true)
291	    public Map<Long, List<Claim>> bySheet(String sheetId) {
292	        return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
293	                .collect(Collectors.groupingBy(Claim::getPersonId));
294	    }
295	
296	    @Transactional(readOnly = true)
297	    public List<Claim> forPerson(String sheetId, long personId) {
298	        return claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
299	    }
300	
301	    /** Add a claim; a date left out takes the sheet's today. Returns the person it belongs to. */
302	    @Transactional
303	    public long add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
304	        Person person = people.findByIdAndSheetId(personId, sheetId)
305	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
306	        LocalDate on = date != null ? date : sheets.today(sheetId);
307	        periods.requireOpen(sheetId, on);
308	        requireNotRetired(person, on);
309	        Rollup.Figures before = rollup.figures(sheetId);
310	        claims.saveAndFlush(new Claim(sheetId, personId, amount, on, note == null ? "" : note));
311	        events.publishEvent(new ClaimChanged("CLAIM_ADDED", sheetId, user, person.getName(), amount, on, null, null));
312	        rollup.changed(sheetId, user, before);
313	        return personId;
314	    }
315	
316	    /**
317	     * Edit a claim's amount, date and note; only a DRAFT can be edited (an open claim is voided and
318	     * added again instead), and an edit is refused when a closed period contains its date or the new one.
319	     * Returns the person it belongs to.
320	     */
321	    @Transactional
322	    public long edit(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note) {
323	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
324	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
325	        LocalDate on = date != null ? date : sheets.today(sheetId);
326	        periods.requireOpen(sheetId, claim.getDate(), on);
327	        if (claim.getStatus() != ClaimStatus.DRAFT) {
328	            throw new ResponseStatusException(HttpStatus.CONFLICT,
329	                    "A " + claim.getStatus() + " claim cannot be edited; void it and add a new one");
330	        }
331	        if (!on.equals(claim.getDate())) {
332	            people.findByIdAndSheetId(claim.getPersonId(), sheetId).ifPresent(p -> requireNotRetired(p, on));
333	        }
334	        Rollup.Figures before = rollup.figures(sheetId);
335	        claim.setAmount(amount);
336	        claim.setDate(on);
337	        claim.setNote(note == null ? "" : note);
338	        claims.flush();
339	        String person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).map(Person::getName).orElse("");
340	        events.publishEvent(new ClaimChanged("CLAIM_EDITED", sheetId, user, person, claim.getAmount(),
341	                claim.getDate(), claim.getNumber(), null));
342	        rollup.changed(sheetId, user, before);
343	        return claim.getPersonId();
344	    }
345	
346	    /**
347	     * Move a claim to a status; a move its status does not allow, settling by the user who opened
348	     * the claim, settling by a clerk a claim whose due is above the clerk limit, or moving a claim dated inside a closed period, is refused and changes nothing.
349	     * Returns the person it belongs to.
350	     */
351	    @Transactional
352	    public long move(String sheetId, String user, long claimId, ClaimStatus next) {
353	        Claim claim = claims.findByIdAndSheetId(claimId, sheetId)
354	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
355	        periods.requireOpen(sheetId, claim.getDate());
356	        if (!claim.getStatus().canBecome(next)) {
357	            throw new ResponseStatusException(HttpStatus.CONFLICT,
358	                    "A " + claim.getStatus() + " claim cannot become " + next);
359	        }
360	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
361	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
362	                    "The user who opened a claim cannot settle it");
363	        }
364	        Rollup.Figures before = rollup.figures(sheetId);
365	        Integer number = claim.getNumber();
366	        if (next == ClaimStatus.OPEN) {
367	            number = sheets.nextClaimNumber(sheetId);
368	            claim.setNumber(number);
369	            claim.setOpenedBy(user);
370	        }
371	        Person owner = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElse(null);
372	        String due = null;
373	        if (next == ClaimStatus.SETTLED) {
374	            BigDecimal fixed;
375	            if (claim.isStated()) {
376	                fixed = claim.getStatedDue();
377	            } else {
378	                fixed = owner == null ? null
379	                        : rates.table(sheetId).due(claim.getAmount(), owner.getGrade(), claim.getDate());
380	            }
381	            access.requireCanSettle(sheetId, user, fixed);
382	            claim.setSettledDue(fixed);
383	            due = fixed == null ? "n/a" : fixed.toPlainString();
384	        }
385	        claim.setStatus(next);
386	        claims.flush();
387	        String person = owner == null ? "" : owner.getName();
388	        String event = switch (next) {
389	            case OPEN -> "CLAIM_OPENED";
390	            case SETTLED -> "CLAIM_SETTLED";
391	            case VOID -> "CLAIM_VOIDED";
392	            case DRAFT -> throw new IllegalStateException();
393	        };
394	        events.publishEvent(new ClaimChanged(event, sheetId, user, person, claim.getAmount(), claim.getDate(), number, due));
395	        rollup.changed(sheetId, user, before);
396	        return claim.getPersonId();
397	    }
398	
399	    /** Refuse a claim dated after its person's retirement date. */
400	    private static void requireNotRetired(Person person, LocalDate date) {
401	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
402	            throw new ResponseStatusException(HttpStatus.CONFLICT,
403	                    person.getName() + " is retired from " + person.getRetiredFrom()
404	                            + "; a claim cannot be dated after that");
405	        }
406	    }
407	}
