578	
579	import java.time.Clock;
580	import java.math.BigDecimal;
581	import java.time.LocalDate;
582	import net.officefloor.hq.app.rollup.Rollup;
583	import org.springframework.dao.DataIntegrityViolationException;
584	import org.springframework.stereotype.Service;
585	import org.springframework.transaction.annotation.Transactional;
586	
587	/**
588	 * Loads a sheet by id, starting an empty one when the id was never used, and keeps the sheet's
589	 * today. The real clock is read only to start a new sheet's today; everything else that depends
590	 * on the date asks {@link #today(String)}.
591	 */
592	@Service
593	public class SheetService {
594	
595	    private final SheetRepository sheets;
596	    private final Rollup rollup;
597	    private final Clock clock = Clock.systemDefaultZone();
598	
599	    public SheetService(SheetRepository sheets, Rollup rollup) {
600	        this.sheets = sheets;
601	        this.rollup = rollup;
602	    }
603	
604	    public Sheet load(String id, String user) {
605	        try {
606	            return loadOrCreate(id, user);
607	        } catch (DataIntegrityViolationException e) {
608	            // Another user started the same sheet at the same moment: theirs is the one.
609	            return sheets.findById(id).orElseThrow(() -> e);
610	        }
611	    }
612	
613	    /** The sheet's floor: the least live due a claim has. */
614	    public BigDecimal floor(String id) {
615	        return sheets.findById(id).map(Sheet::getFloor).orElse(Sheet.DEFAULT_FLOOR);
616	    }
617	
618	    /** The sheet's terms: the days a claim has to be paid by, from its date. */
619	    public int terms(String id) {
620	        return sheets.findById(id).map(Sheet::getTerms).orElse(Sheet.DEFAULT_TERMS);
621	    }
622	
623	    /** The sheet's today: the date to use for every decision and default date on the sheet. */
624	    public LocalDate today(String id) {
625	        return sheets.findById(id).map(Sheet::getToday).orElseGet(() -> LocalDate.now(clock));
626	    }
627	
628	    /**
629	     * The next claim number on the sheet: 1 for the first, then 2, and so on. Two users taking one
630	     * at the same moment wait on each other, so no number is given twice or skipped.
631	     */
632	    @Transactional
633	    public int nextClaimNumber(String id) {
634	        if (sheets.bumpClaimNumber(id) != 1) {
635	            throw new IllegalStateException("No such sheet " + id);
636	        }
637	        return sheets.lastClaimNumber(id);
638	    }
639	
640	    /**
641	     * Change the sheet's today, starting the sheet if it was never loaded. The change has no audit
642	     * line of its own, only the figures it moves.
643	     */
644	    @Transactional
645	    public Sheet setToday(String id, String user, LocalDate today) {
646	        Sheet sheet = load(id, user);
647	        Rollup.Figures before = rollup.figures(id);
648	        sheet.setToday(today);
649	        Sheet saved = sheets.saveAndFlush(sheet);
650	        rollup.changed(id, user, before);
651	        return saved;
652	    }
653	
654	    private Sheet loadOrCreate(String id, String user) {
655	        return sheets.findById(id)
656	                .orElseGet(() -> sheets.saveAndFlush(new Sheet(id, user, LocalDate.now(clock))));
657	    }
658	}
659	package net.officefloor.hq.app.access;
660	
661	import java.math.BigDecimal;
662	import java.math.RoundingMode;
663	import java.util.List;
664	import net.officefloor.hq.app.rollup.Rollup;
665	import net.officefloor.hq.app.sheet.Sheet;
666	import net.officefloor.hq.app.sheet.SheetRepository;
667	import net.officefloor.hq.app.sheet.SheetService;
668	import org.springframework.context.ApplicationEventPublisher;
669	import org.springframework.stereotype.Service;
670	import org.springframework.transaction.annotation.Transactional;
671	
672	/**
673	 * Who may do what on a sheet: the role each user name has (clerk unless set to steward) and the
674	 * clerk limit, the most due a clerk may settle on a claim (none: no limit); and the sheet's floor, the
675	 * least live due a claim has; and its terms, the days a claim has to be paid by from its date.
676	 */
677	@Service
678	public class AccessService {
679	
680	    public static final String CLERK_LIMIT = "clerk-limit";
681	
682	    public static final String FLOOR = "floor";
683	
684	    public static final String TERMS = "terms";
685	
686	    private final SheetRoleRepository roles;
687	    private final SheetRepository sheetRows;
688	    private final SheetService sheets;
689	    private final Rollup rollup;
690	    private final ApplicationEventPublisher events;
691	
692	    public AccessService(SheetRoleRepository roles, SheetRepository sheetRows, SheetService sheets,
693	            Rollup rollup, ApplicationEventPublisher events) {
694	        this.rollup = rollup;
695	        this.roles = roles;
696	        this.sheetRows = sheetRows;
697	        this.sheets = sheets;
698	        this.events = events;
699	    }
700	
701	    /** The roles set on the sheet, by user name. */
702	    @Transactional(readOnly = true)
703	    public List<SheetRole> roles(String sheetId) {
704	        return roles.findBySheetIdOrderByUserName(sheetId);
705	    }
706	
707	    /** The user's role on the sheet: clerk unless one was set. */
708	    @Transactional(readOnly = true)
709	    public Role roleOf(String sheetId, String user) {
710	        return roles.findBySheetIdAndUserName(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
711	    }
712	
713	    @Transactional(readOnly = true)
714	    public BigDecimal clerkLimit(String sheetId) {
715	        return sheetRows.findById(sheetId).map(Sheet::getClerkLimit).orElse(null);
716	    }
717	
718	    @Transactional(readOnly = true)
719	    public BigDecimal floor(String sheetId) {
720	        return sheets.floor(sheetId);
721	    }
722	
723	    @Transactional(readOnly = true)
724	    public int terms(String sheetId) {
725	        return sheets.terms(sheetId);
726	    }
727	
728	    /** Give a user name a role on the sheet, replacing the one it had. */
729	    @Transactional
730	    public SheetRole setRole(String sheetId, String user, String name, Role role) {
731	        sheets.load(sheetId, user);
732	        SheetRole row = roles.findBySheetIdAndUserName(sheetId, name).orElse(null);
733	        if (row == null) {
734	            row = roles.saveAndFlush(new SheetRole(sheetId, name, role));
735	        } else {
736	            row.setRole(role);
737	            roles.flush();
738	        }
739	        events.publishEvent(new RoleSet(sheetId, user, name, role.key()));
740	        return row;
741	    }
742	
743	    /**
744	     * Save the settings given, as written (blank: none, or the default), in one change; a setting left
745	     * out (null) is kept as it is.
746	     */
747	    @Transactional
748	    public void setSettings(String sheetId, String user, String clerkLimit, String floor, String terms) {
749	        if (clerkLimit != null) {
750	            setClerkLimit(sheetId, user, clerkLimit.isEmpty() ? null : new BigDecimal(clerkLimit));
751	        }
752	        if (floor != null) {
753	            setFloor(sheetId, user, floor.isEmpty() ? null : new BigDecimal(floor));
754	        }
755	        if (terms != null) {
756	            setTerms(sheetId, user, terms.isEmpty() ? null : Integer.valueOf(terms));
757	        }
758	    }
759	
760	    /**
761	     * Save the sheet's terms in days; null puts back the ones a sheet starts with. Every claim's due-by
762	     * moves with them; no due figure does.
763	     */
764	    @Transactional
765	    public int setTerms(String sheetId, String user, Integer terms) {
766	        Sheet sheet = sheets.load(sheetId, user);
767	        int days = terms == null ? Sheet.DEFAULT_TERMS : terms;
768	        sheet.setTerms(days);
769	        sheetRows.saveAndFlush(sheet);
770	        events.publishEvent(new SettingChanged(sheetId, user, TERMS, Integer.toString(days)));
771	        return days;
772	    }
773	
774	    /** Save the sheet's clerk limit; null removes it. */
775	    @Transactional
776	    public BigDecimal setClerkLimit(String sheetId, String user, BigDecimal limit) {
777	        Sheet sheet = sheets.load(sheetId, user);
778	        BigDecimal scaled = limit == null ? null : limit.setScale(2, RoundingMode.HALF_UP);
779	        sheet.setClerkLimit(scaled);
780	        sheetRows.saveAndFlush(sheet);
781	        events.publishEvent(new SettingChanged(sheetId, user, CLERK_LIMIT, scaled == null ? "" : scaled.toPlainString()));
782	        return scaled;
783	    }
784	
785	    /**
786	     * Save the sheet's floor; null puts back the one a sheet starts with. Every live due moves with it;
787	     * a settled, stated or closed figure keeps the one it had.
788	     */
789	    @Transactional
790	    public BigDecimal setFloor(String sheetId, String user, BigDecimal floor) {
791	        Sheet sheet = sheets.load(sheetId, user);
792	        BigDecimal scaled = floor == null ? Sheet.DEFAULT_FLOOR : floor.setScale(2, RoundingMode.HALF_UP);
793	        Rollup.Figures before = rollup.figures(sheetId);
794	        sheet.setFloor(scaled);
795	        sheetRows.saveAndFlush(sheet);
796	        events.publishEvent(new SettingChanged(sheetId, user, FLOOR, scaled.toPlainString()));
797	        rollup.changed(sheetId, user, before);
798	        return scaled;
799	    }
800	
801	    /**
802	     * Refuse a settle by a clerk of a claim whose due is above the clerk limit. A due of n/a (null)
803	     * is within any limit; a steward settles anything.
804	     */
805	    @Transactional(readOnly = true)
806	    public void requireCanSettle(String sheetId, String user, BigDecimal due) {
807	        if (due == null) {
808	            return;
809	        }
810	        BigDecimal limit = clerkLimit(sheetId);
