package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet, keyed by the id a user types; created the first time it is loaded. */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The floor a sheet starts with. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms a sheet starts with, in days. */
    public static final int DEFAULT_TERMS = 14;

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    /** The sheet's today: the date every date-dependent decision on the sheet uses. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The number given to the last claim opened on the sheet; 0 before any is opened. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** The most due a clerk may settle on a claim; null when there is no limit. */
    @Column(name = "clerk_limit", precision = 14, scale = 2)
    private BigDecimal clerkLimit;

    /** The least live due a claim has; 1.00 until set. */
    @Column(name = "due_floor", nullable = false, precision = 14, scale = 2)
    private BigDecimal floor = DEFAULT_FLOOR;

    /** The days a claim has to be paid by, from its date; 14 until set. */
    @Column(name = "terms", nullable = false)
    private int terms = DEFAULT_TERMS;

    protected Sheet() {
    }

    public Sheet(String id, String createdBy, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.today = today;
    }

    public String getId() {
        return id;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    public BigDecimal getClerkLimit() {
        return clerkLimit;
    }

    public void setClerkLimit(BigDecimal clerkLimit) {
        this.clerkLimit = clerkLimit;
    }

    public BigDecimal getFloor() {
        return floor;
    }

    public void setFloor(BigDecimal floor) {
        this.floor = floor;
    }

    public int getTerms() {
        return terms;
    }

    public void setTerms(int terms) {
        this.terms = terms;
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.LockModeType;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface SheetRepository extends JpaRepository<Sheet, String> {

    /** Take the sheet's next claim number; the row stays locked until the transaction ends. */
    @Modifying(flushAutomatically = true)
    @Query("update Sheet s set s.lastClaimNumber = s.lastClaimNumber + 1 where s.id = :id")
    int bumpClaimNumber(@Param("id") String id);

    @Query("select s.lastClaimNumber from Sheet s where s.id = :id")
    int lastClaimNumber(@Param("id") String id);

    /** Lock the sheet's row until the transaction ends, so changes checked against the whole sheet take turns. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select s from Sheet s where s.id = :id")
    Sheet lockById(@Param("id") String id);
}
package net.officefloor.hq.app.sheet;

import java.time.Clock;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.rollup.Rollup;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Loads a sheet by id, starting an empty one when the id was never used, and keeps the sheet's
 * today. The real clock is read only to start a new sheet's today; everything else that depends
 * on the date asks {@link #today(String)}.
 */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Rollup rollup;
    private final Clock clock = Clock.systemDefaultZone();

    public SheetService(SheetRepository sheets, Rollup rollup) {
        this.sheets = sheets;
        this.rollup = rollup;
    }

    public Sheet load(String id, String user) {
        try {
            return loadOrCreate(id, user);
        } catch (DataIntegrityViolationException e) {
            // Another user started the same sheet at the same moment: theirs is the one.
            return sheets.findById(id).orElseThrow(() -> e);
        }
    }

    /** The sheet's floor: the least live due a claim has. */
    public BigDecimal floor(String id) {
        return sheets.findById(id).map(Sheet::getFloor).orElse(Sheet.DEFAULT_FLOOR);
    }

    /** The sheet's terms: the days a claim has to be paid by, from its date. */
    public int terms(String id) {
        return sheets.findById(id).map(Sheet::getTerms).orElse(Sheet.DEFAULT_TERMS);
    }

    /** The sheet's today: the date to use for every decision and default date on the sheet. */
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElseGet(() -> LocalDate.now(clock));
    }

    /**
     * The next claim number on the sheet: 1 for the first, then 2, and so on. Two users taking one
     * at the same moment wait on each other, so no number is given twice or skipped.
     */
    @Transactional
    public int nextClaimNumber(String id) {
        if (sheets.bumpClaimNumber(id) != 1) {
            throw new IllegalStateException("No such sheet " + id);
        }
        return sheets.lastClaimNumber(id);
    }

    /**
     * Change the sheet's today, starting the sheet if it was never loaded. The change has no audit
     * line of its own, only the figures it moves.
     */
    @Transactional
    public Sheet setToday(String id, String user, LocalDate today) {
        Sheet sheet = load(id, user);
        Rollup.Figures before = rollup.figures(id);
        sheet.setToday(today);
        Sheet saved = sheets.saveAndFlush(sheet);
        rollup.changed(id, user, before);
        return saved;
    }

    private Sheet loadOrCreate(String id, String user) {
        return sheets.findById(id)
                .orElseGet(() -> sheets.saveAndFlush(new Sheet(id, user, LocalDate.now(clock))));
    }
}
package net.officefloor.hq.app.access;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Who may do what on a sheet: the role each user name has (clerk unless set to steward) and the
 * clerk limit, the most due a clerk may settle on a claim (none: no limit); and the sheet's floor, the
 * least live due a claim has; and its terms, the days a claim has to be paid by from its date.
 */
@Service
public class AccessService {

    public static final String CLERK_LIMIT = "clerk-limit";

    public static final String FLOOR = "floor";

    public static final String TERMS = "terms";

    private final SheetRoleRepository roles;
    private final SheetRepository sheetRows;
    private final SheetService sheets;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;

    public AccessService(SheetRoleRepository roles, SheetRepository sheetRows, SheetService sheets,
            Rollup rollup, ApplicationEventPublisher events) {
        this.rollup = rollup;
        this.roles = roles;
        this.sheetRows = sheetRows;
        this.sheets = sheets;
        this.events = events;
    }

    /** The roles set on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserName(sheetId);
    }

    /** The user's role on the sheet: clerk unless one was set. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUserName(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return sheetRows.findById(sheetId).map(Sheet::getClerkLimit).orElse(null);
    }

    @Transactional(readOnly = true)
    public BigDecimal floor(String sheetId) {
        return sheets.floor(sheetId);
    }

    @Transactional(readOnly = true)
    public int terms(String sheetId) {
        return sheets.terms(sheetId);
    }

    /** Give a user name a role on the sheet, replacing the one it had. */
    @Transactional
    public SheetRole setRole(String sheetId, String user, String name, Role role) {
        sheets.load(sheetId, user);
        SheetRole row = roles.findBySheetIdAndUserName(sheetId, name).orElse(null);
        if (row == null) {
            row = roles.saveAndFlush(new SheetRole(sheetId, name, role));
        } else {
            row.setRole(role);
            roles.flush();
        }
        events.publishEvent(new RoleSet(sheetId, user, name, role.key()));
        return row;
    }

    /**
     * Save the settings given, as written (blank: none, or the default), in one change; a setting left
     * out (null) is kept as it is.
     */
    @Transactional
    public void setSettings(String sheetId, String user, String clerkLimit, String floor, String terms) {
        if (clerkLimit != null) {
            setClerkLimit(sheetId, user, clerkLimit.isEmpty() ? null : new BigDecimal(clerkLimit));
        }
        if (floor != null) {
            setFloor(sheetId, user, floor.isEmpty() ? null : new BigDecimal(floor));
        }
        if (terms != null) {
            setTerms(sheetId, user, terms.isEmpty() ? null : Integer.valueOf(terms));
        }
    }

    /**
     * Save the sheet's terms in days; null puts back the ones a sheet starts with. Every claim's due-by
     * moves with them; no due figure does.
     */
    @Transactional
    public int setTerms(String sheetId, String user, Integer terms) {
        Sheet sheet = sheets.load(sheetId, user);
        int days = terms == null ? Sheet.DEFAULT_TERMS : terms;
        sheet.setTerms(days);
        sheetRows.saveAndFlush(sheet);
        events.publishEvent(new SettingChanged(sheetId, user, TERMS, Integer.toString(days)));
        return days;
    }

    /** Save the sheet's clerk limit; null removes it. */
    @Transactional
    public BigDecimal setClerkLimit(String sheetId, String user, BigDecimal limit) {
        Sheet sheet = sheets.load(sheetId, user);
        BigDecimal scaled = limit == null ? null : limit.setScale(2, RoundingMode.HALF_UP);
        sheet.setClerkLimit(scaled);
        sheetRows.saveAndFlush(sheet);
        events.publishEvent(new SettingChanged(sheetId, user, CLERK_LIMIT, scaled == null ? "" : scaled.toPlainString()));
        return scaled;
    }

    /**
     * Save the sheet's floor; null puts back the one a sheet starts with. Every live due moves with it;
     * a settled, stated or closed figure keeps the one it had.
     */
    @Transactional
    public BigDecimal setFloor(String sheetId, String user, BigDecimal floor) {
        Sheet sheet = sheets.load(sheetId, user);
        BigDecimal scaled = floor == null ? Sheet.DEFAULT_FLOOR : floor.setScale(2, RoundingMode.HALF_UP);
        Rollup.Figures before = rollup.figures(sheetId);
        sheet.setFloor(scaled);
        sheetRows.saveAndFlush(sheet);
        events.publishEvent(new SettingChanged(sheetId, user, FLOOR, scaled.toPlainString()));
        rollup.changed(sheetId, user, before);
        return scaled;
    }

    /**
     * Refuse a settle by a clerk of a claim whose due is above the clerk limit. A due of n/a (null)
     * is within any limit; a steward settles anything.
     */
    @Transactional(readOnly = true)
    public void requireCanSettle(String sheetId, String user, BigDecimal due) {
        if (due == null) {
            return;
        }
        BigDecimal limit = clerkLimit(sheetId);
        if (limit != null && due.compareTo(limit) > 0 && roleOf(sheetId, user) == Role.CLERK) {
            throw new OverClerkLimit(due, limit);
        }
    }
}
